        assertEquals(new BigDecimal("0.00"), march.discount());
        assertEquals(new BigDecimal("820.00"), march.total());
        assertEquals(new BigDecimal("520.00"), july.total());
        assertEquals(new BigDecimal("1200.00"), suiteWeekend.total());
