        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(noCode)));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(unknown)));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(lowerCase)));
        assertEquals(new BigDecimal("439.82"), service.create(tecnosul).price().total());
